import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { findJob, isWorkerUp, listJobs, submitJob, toJob } from './jobs.ts';

const MAX_BODY_BYTES = 100 * 1024;
const MAX_INPUT_LENGTH = 1000;
const STEPS_RANGE = [1, 20] as const;
const FAIL_ATTEMPTS_RANGE = [0, 5] as const;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

function readBody(req: IncomingMessage): Promise<{ text: string } | { tooLarge: true }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { tooLarge: true } : { text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntegerIn(v: unknown, [min, max]: readonly [number, number]): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

interface ValidJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

/** Validates a submission. Returns the job with defaults applied, or the offending fields. */
function validateSubmission(req: IncomingMessage, rawBody: string): ValidJob | FieldError[] {
  const fields: FieldError[] = [];

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    return [{ field: 'body', message: 'Content-Type must be application/json.' }];
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return [{ field: 'body', message: 'Body must be valid JSON.' }];
  }
  if (!isPlainObject(parsed)) return [{ field: 'body', message: 'Body must be a JSON object.' }];

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = parsed;
  if (!('input' in parsed)) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  if ('steps' in parsed && !isIntegerIn(steps, STEPS_RANGE)) {
    fields.push({ field: 'steps', message: `Must be an integer from ${STEPS_RANGE[0]} to ${STEPS_RANGE[1]}.` });
  }
  if ('failAttempts' in parsed && !isIntegerIn(failAttempts, FAIL_ATTEMPTS_RANGE)) {
    fields.push({
      field: 'failAttempts',
      message: `Must be an integer from ${FAIL_ATTEMPTS_RANGE[0]} to ${FAIL_ATTEMPTS_RANGE[1]}.`,
    });
  }

  const rawKey = req.headers['idempotency-key'];
  // A repeated header arrives as an array; joining it makes the pattern check reject it.
  const key = Array.isArray(rawKey) ? rawKey.join(', ') : rawKey;
  if (key !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (fields.length > 0) return fields;
  return {
    input: input as string,
    steps: steps as number,
    failAttempts: failAttempts as number,
    idempotencyKey: key,
  };
}

async function handlePostJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  if ('tooLarge' in body) {
    return sendError(res, 400, 'invalid_request', 'Invalid job submission.', [
      { field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` },
    ]);
  }

  const valid = validateSubmission(req, body.text);
  if (Array.isArray(valid)) {
    return sendError(res, 400, 'invalid_request', 'Invalid job submission.', valid);
  }

  const outcome = submitJob(db, valid);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.job));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = findJob(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
  sendJson(res, 200, toJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
